-- HCL Intern Nexus permanent Supabase schema. Safe to run more than once.
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL DEFAULT '', username TEXT UNIQUE, email TEXT UNIQUE NOT NULL, role TEXT NOT NULL DEFAULT 'student', password_hash TEXT NOT NULL DEFAULT '', password TEXT, is_active INTEGER NOT NULL DEFAULT 1, start_date TEXT, end_date TEXT, last_login TEXT, created_at TEXT NOT NULL DEFAULT (NOW() AT TIME ZONE 'utc')::TEXT);
CREATE TABLE IF NOT EXISTS activity (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, seconds INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS meetings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id BIGINT, mentor_id BIGINT, title TEXT NOT NULL, meeting_date TEXT, meeting_time TEXT, meeting_link TEXT, status TEXT DEFAULT 'scheduled', created_at TEXT);
CREATE TABLE IF NOT EXISTS notices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, message TEXT NOT NULL, audience TEXT DEFAULT 'student', created_at TEXT NOT NULL, created_by BIGINT);
CREATE TABLE IF NOT EXISTS resources (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, topic TEXT NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL, resource_type TEXT NOT NULL DEFAULT 'blog', created_by BIGINT, description TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_resources (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, resource_key TEXT NOT NULL, resource_type TEXT NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL, topic TEXT NOT NULL, saved INTEGER NOT NULL DEFAULT 0, viewed INTEGER NOT NULL DEFAULT 0, last_viewed_at TEXT, progress_seconds INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0, UNIQUE(user_id, resource_key));
CREATE TABLE IF NOT EXISTS private_messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sender_id BIGINT NOT NULL, recipient_id BIGINT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT);
CREATE TABLE IF NOT EXISTS coding_lab_attempts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, question_key TEXT NOT NULL, category TEXT NOT NULL, code TEXT NOT NULL, passed INTEGER NOT NULL DEFAULT 0, feedback TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deletion_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, reason TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, reviewed_at TEXT, reviewed_by BIGINT);
